    const refreshSecret = 'refresh-secret'

    const validAccess = async (overrides: Record<string, unknown> = {}) =>
      sign(
        { sub: 'user-1', exp: Math.floor(Date.now() / 1000) + 3600, ...overrides },
        secret,
        'HS256'
      )

    const expiredAccess = async (overrides: Record<string, unknown> = {}) =>
      sign(
        { sub: 'user-1', exp: Math.floor(Date.now() / 1000) - 60, ...overrides },
        secret,
        'HS256'
      )

