        { sub: 'user-1', exp: Math.floor(Date.now() / 1000) + 86400, ...overrides },
        key,
        'HS256'
      )

    it('Should authorize when access token is valid', async () => {
      const onRefresh = vi.fn(async () => 'should-not-be-called')
      const app = new Hono()
