        '/auth/*',
        jwtRefresh({
          secret,
          refreshSecret,
          alg: 'HS256',
          onRefresh,
        })
      )
      app.get('/auth/me', (c) => c.json(c.get('jwtPayload')))

      const token = await validAccess()
      const req = new Request('http://localhost/auth/me')
      req.headers.set('Authorization', `Bearer ${token}`)
      const res = await app.request(req)

      expect(res.status).toBe(200)
      expect(((await res.json()) as { sub: string }).sub).toBe('user-1')
      expect(res.headers.get('X-Access-Token')).toBeNull()
      expect(onRefresh).not.toHaveBeenCalled()
    })

