      const newToken = await sign(
        { sub: 'user-1', exp: Math.floor(Date.now() / 1000) + 3600, refreshed: true },
        secret,
        'HS256'
      )
      const onRefresh = vi.fn(async () => newToken)

      const app = new Hono()
      app.use(
        '/auth/*',
        jwtRefresh({
          secret,
          refreshSecret,
          alg: 'HS256',
          onRefresh,
        })
      )
