      const access = await expiredAccess()
      const refresh = await validRefresh()
      const req = new Request('http://localhost/auth/me', {
        headers: new Headers({
          Authorization: `Bearer ${access}`,
          Cookie: `refresh_token=${refresh}`,
        }),
      })
