        jwtRefresh({
          secret,
          refreshSecret,
          refreshCookie: 'my_refresh',
          alg: 'HS256',
          onRefresh,
        })
      )
      app.get('/auth/me', (c) => c.json(c.get('jwtPayload')))

      const access = await expiredAccess()
      const refresh = await validRefresh()
      const req = new Request('http://localhost/auth/me', {
