      expect(onRefresh).toHaveBeenCalledTimes(1)
      expect(res.headers.get('X-Access-Token')).toBe(newToken)
    })

    it('Should 401 when access token is expired and refresh token is invalid', async () => {
      const onRefresh = vi.fn(async () => 'never')
      const app = new Hono()
      app.use(
        '/auth/*',
        jwtRefresh({
          secret,
          refreshSecret,
          alg: 'HS256',
          onRefresh,
        })
      )
