          Cookie: 'refresh_token=garbage.token.value',
        }),
      })
      const res = await app.request(req)

      expect(res.status).toBe(401)
      expect(onRefresh).not.toHaveBeenCalled()
    })

    it('Should 401 when access token is expired and no refresh cookie is present', async () => {
      const onRefresh = vi.fn(async () => 'never')
      const app = new Hono()
      app.use(
        '/auth/*',
        jwtRefresh({
