      const onRefresh = vi.fn(async () => 'never')
      const app = new Hono()
      app.use(
        '/auth/*',
        jwtRefresh({
          secret,
          refreshSecret,
          alg: 'HS256',
          onRefresh,
        })
      )
      app.get('/auth/me', (c) => c.json(c.get('jwtPayload')))

